SELECT r.id, LEFT(v.name, 100) AS name, LEFT(v.description, 500) AS description, JSON_UNQUOTE(JSON_EXTRACT(v.config_json, '$.icon')) AS icon, JSON_UNQUOTE(JSON_EXTRACT(v.config_json, '$.color')) AS color FROM resource r JOIN resource_version v ON v.enterprise_id = r.enterprise_id AND v.resource_id = r.id AND v.id = r.published_version_id LEFT JOIN agent_listing l ON l.enterprise_id = r.enterprise_id AND l.agent_id = r.id LEFT JOIN agent_hire h ON h.enterprise_id = r.enterprise_id AND h.agent_id = r.id AND h.user_id = #{user} WHERE r.enterprise_id = #{enterprise} AND r.kind = 'agent' AND r.deleted_at IS NULL AND LOCATE(#{query}, v.name) > 0 AND ((#{mine} AND h.status IN ('active','paused')) OR (
AND l.listed = TRUE AND v.status = 'available')
) ORDER BY v.published_at DESC, r.id DESC LIMIT 10

